-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT ol.location, count(distinct ol.ORDER_NO)as \"ACTIVE ORDERS\" FROM MFCS_RDS.RDS_WV_ORDHEAD oh     JOIN MFCS_RDS.RDS_WV_ORDLOC ol ON oh.ORDER_NO = ol.ORDER_NO WHERE oh.STATUS IN ('A') group by ol.location order by count(distinct ol.ORDER_NO) desc </ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>LOCATION</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>ACTIVE ORDERS</ds:name><ds:datatype>number</ds:datatype></ds:column></ds:columns></ds:table></ds:tables><ds:prepareTables><ds:table name=\"Data\" transformed=\"true\"><ds:columns><ds:column><ds:name>LOCATION</ds:name></ds:column><ds:column><ds:name>ACTIVE ORDERS</ds:name></ds:column></ds:columns></ds:table></ds:prepareTables><ds:outputTables><ds:table disableXSACache=\"false\" name=\"Data\"><ds:columns><ds:column exclude=\"false\"><ds:name>LOCATION</ds:name><ds:display_names><ds:display_name><ds:name>LOCATION</ds:name><ds:locale>sys</ds:locale></ds:display_name></ds:display_names><ds:datatype>number</ds:datatype><ds:sourceexpr>\"LOCATION\"</ds:sourceexpr><ds:aggr_rule>none</ds:aggr_rule></ds:column><ds:column exclude=\"false\"><ds:name>ACTIVE ORDERS</ds:name><ds:display_names><ds:display_name><ds:name>ACTIVE ORDERS</ds:name><ds:locale>sys</ds:locale></ds:display_name></ds:display_names><ds:datatype>number</ds:datatype><ds:sourceexpr>\"ACTIVE ORDERS\"</ds:sourceexpr><ds:aggr_rule>sum</ds:aggr_rule></ds:column></ds:columns><ds:data-access-mode>auto</ds:data-access-mode></ds:table></ds:outputTables><ds:uiOptions>{\"version\":\"v5.2\",\"outputColumns\":[{\"prepColumnName\":\"LOCATION\",\"isUserCalculation\":false},{\"subjectArea\":\"XSA('ReCommon'.'090e5cdd-4909-4c2a-b9c8-a127602f4625')\",\"tableName\":\"Columns\",\"prepColumnName\":\"ACTIVE ORDERS\"}],\"transforms\":[{\"id\":\"1\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"LOCATION\"],\"expressionSourceColumns\":[\"LOCATION\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"LOCATION\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"LOCATION\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":null}],\"recommendations\":[],\"dataSubsetInfos\":{\"queryEditMode\":1,\"filterbarSettings\":{},\"uiSqlStatement\":\"

